def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            value = f"{local}@{domain}"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""
        return value

    def normalize_phone(value):
        value = re.split(r"x|ext|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip().split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            value = value.title()
        return value

    n = len(rows)
    prepared = []
    for index, row in enumerate(rows):
        updated = parse_updated(row["updated"])
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])
        prepared.append({
            "index": index,
            "row": row,
            "updated_dt": updated,
            "email": email,
            "phone": phone,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "opted_out": row["opted_out"].strip().lower() in {"y", "yes", "true", "1"},
        })

    # Union-find makes duplicate matching transitive.
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_name_owner = {}
    eligible = set()

    for item in prepared:
        i = item["index"]
        if not item["email"] and not item["phone"]:
            continue
        eligible.add(i)

        if item["email"]:
            if item["email"] in email_owner:
                union(i, email_owner[item["email"]])
            else:
                email_owner[item["email"]] = i

        last_name = item["last_name"].casefold()
        if item["phone"] and last_name:
            key = (item["phone"], last_name)
            if key in phone_name_owner:
                union(i, phone_name_owner[key])
            else:
                phone_name_owner[key] = i

    groups = {}
    for i in eligible:
        groups.setdefault(find(i), []).append(prepared[i])

    def pick(group, field, valid_only=False):
        candidates = [
            item for item in group
            if item[field] and (not valid_only or item[field])
        ]
        if not candidates:
            return ""
        chosen = max(
            candidates,
            key=lambda item: (
                item["source"] == "manual",
                item["updated_dt"],
                -item["index"],
            ),
        )
        return chosen[field]

    output = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(x["index"] for x in group))
    for group in ordered_groups:
        tags = set()
        for item in group:
            for tag in re.split(r"[;,]", item["row"]["tags"]):
                tag = tag.strip().lower()
                if tag:
                    tags.add(tag)

        latest = max(item["updated_dt"] for item in group)
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email", valid_only=True),
            "phone": pick(group, "phone", valid_only=True),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(item["opted_out"] for item in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
